function updateFlipSim() {
    const k = parseInt(document.getElementById('input-mult-k').value, 10);
    document.getElementById('badge-mult-k').innerText = 'k = ' + k;

    const a = 2 * k;
    const b = 5 * k;

    let sym = '<';
    if (a > b) sym = '>';
    else if (a === b) sym = '=';

    document.getElementById('scaled-ineq-readout').innerText = `${a} ${sym} ${b}`;

    const box = document.getElementById('flip-alert-box');
    const msg = document.getElementById('flip-status-msg');

    if (k < 0) {
        box.style.background = 'rgba(225, 29, 72, 0.15)';
        box.style.borderColor = '#f43f5e';
        msg.style.color = '#f43f5e';
        msg.innerHTML = '<i class="fas fa-sync-alt"></i> REVERSED: Symbol flipped from < to >';
    } else if (k === 0) {
        box.style.background = 'rgba(245, 158, 11, 0.15)';
        box.style.borderColor = '#f59e0b';
        msg.style.color = '#f59e0b';
        msg.innerHTML = '<i class="fas fa-equals"></i> EQUAL: Multiplying by 0 gives 0 = 0';
    } else {
        box.style.background = 'rgba(16, 185, 129, 0.15)';
        box.style.borderColor = '#10b981';
        msg.style.color = '#10b981';
        msg.innerHTML = '<i class="fas fa-arrow-right"></i> PRESERVED: Direction remained <';
    }
}

document.addEventListener('DOMContentLoaded', () => {
    updateFlipSim();
});

